// Generated by esquadro: do not edit. A realm's accounts, for those who
// administer them: its roles (as the model declares them), the accounts
// with their roles and status, invitations, roles changed, accounts
// disabled, signed out or deleted; never one's own way out.
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { useNavigate, useSearch } from "@tanstack/react-router"
import { Ban, ChevronLeft, ChevronRight, KeyRound, LogOut, MailPlus, MoreHorizontal, RotateCw, ShieldCheck, Trash2, UserCheck, UserPlus } from "lucide-react"
import { useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Checkbox } from "@/components/ui/checkbox"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Field, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { isApiError } from "@api"
import { api } from "../api.ts"
import type { AccountRealm } from "../accounts.gen.ts"
import { base, locale } from "../config.ts"
import { useSession } from "./auth.tsx"
import { ask } from "./confirm.tsx"
import { describe, fieldErrors, fieldMessage } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import { PageHeader } from "./page.tsx"
import { initials } from "./picture.tsx"
import { SearchBox } from "./search.tsx"
import { ErrorState } from "./states.tsx"
import { toast } from "./toast.tsx"

type Status = "active" | "invited" | "unverified" | "disabled"

interface Account {
  id: string
  email: string
  name: string
  fields: Record<string, unknown>
  roles: string[]
  status: Status
  last_seen_at: string | null
  created_at: string
}

interface RoleInfo {
  name: string
  permissions: string[]
  accounts: number
  administers: boolean
}

interface Accounts {
  list(query: Record<string, string | number | undefined>): Promise<{ items: Account[]; page: number; total: number; total_pages: number }>
  invite(i: { email: string; roles: string[]; fields: Record<string, unknown>; redirect: string }): Promise<Account>
  reinvite(id: string, redirect?: string): Promise<void>
  setRoles(id: string, roles: string[]): Promise<Account>
  disable(id: string): Promise<Account>
  enable(id: string): Promise<Account>
  endSessions(id: string): Promise<void>
  remove(id: string): Promise<void>
  roles(): Promise<RoleInfo[]>
}

/** The client's routes of a realm's accounts. */
function accountsOf(realm: AccountRealm): Accounts {
  return (api.identity as unknown as Record<string, { accounts: Accounts }>)[realm.key].accounts
}

/** Whether the session administers the realm's accounts: one of its admins' rules. */
export function administers(session: { realm: string; roles: string[] } | null, realm: AccountRealm): boolean {
  return allowedBy(session, realm.admins)
}

/** Whether the session is one of the realm.role rules: user.admin. */
export function allowedBy(session: { realm: string; roles: string[] } | null, rules: readonly string[]): boolean {
  if (!session) return false
  return rules.some((rule) => {
    const [name, role] = rule.split(".")
    return name === session.realm && (!role || session.roles.includes(role))
  })
}

const STATUS: Record<Status, { dot: string; text: string }> = {
  active: { dot: "bg-emerald-500", text: "text-emerald-600 dark:text-emerald-400" },
  invited: { dot: "bg-amber-500", text: "text-amber-600 dark:text-amber-400" },
  unverified: { dot: "bg-sky-500", text: "text-sky-600 dark:text-sky-400" },
  disabled: { dot: "bg-neutral-400", text: "text-muted-foreground" },
}

const statusLabel = (s: Status) => t(`account_${s}`)
const roleLabel = (r: string) => capitalize(r.replaceAll("_", " "))

/** When an account was last seen, as people say it: 3 hours ago, never. */
export function seen(at: string | null): string {
  if (!at) return t("never")
  const seconds = (new Date(at).getTime() - Date.now()) / 1000
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
  for (const [unit, size] of [["year", 31536000], ["month", 2592000], ["week", 604800], ["day", 86400], ["hour", 3600], ["minute", 60]] as const) {
    if (Math.abs(seconds) >= size) return rtf.format(Math.round(seconds / size), unit)
  }
  return t("justNow")
}

/** The page that opens an invitation's link: choosing the password, greeted. */
const inviteRedirect = () => `${base}reset-password?invite=1`

/**
 * A realm's accounts: its roles in cards, the accounts in a table with a
 * search and filters (in the URL), invitations and what may be done to each.
 */
export function AccountsAdmin({ realm }: { realm: AccountRealm }) {
  const session = useSession()
  const search = useSearch({ strict: false }) as { q?: string; role?: string; status?: Status; page?: number }
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const accounts = accountsOf(realm)
  const [inviting, setInviting] = useState(false)
  const [editing, setEditing] = useState<Account | null>(null)
  const set = (changes: Partial<typeof search>) =>
    navigate({ to: ".", search: (prev: Record<string, unknown>) => ({ ...prev, ...changes }) as never, replace: true })
  const query = { q: search.q || undefined, role: search.role, status: search.status, page: search.page ?? 1, per_page: 20 }
  const list = useQuery({ queryKey: ["accounts", realm.name, query], queryFn: () => accounts.list(query), placeholderData: (prev) => prev })
  const roles = useQuery({ queryKey: ["accounts", realm.name, "roles"], queryFn: () => accounts.roles() })
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["accounts", realm.name] })
  const act = useMutation({
    mutationFn: (run: () => Promise<unknown>) => run(),
    onSuccess: () => refresh(),
    onError: (e) => toast(describe(e), "error"),
  })
  const mine = (a: Account) => session?.realm === realm.name && session?.id === a.id
  const page = list.data

  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        title={realm.label}
        description={t("accountsHint")}
        actions={
          <Button onClick={() => setInviting(true)}>
            <UserPlus /> {t("invite")}
          </Button>
        }
      />
      {/* The roles, as the model declares them. */}
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {(roles.data ?? realm.roles.map((name) => ({ name, permissions: [], accounts: 0, administers: false }))).map((r) => (
          <Card key={r.name} className="gap-0 py-0">
            <CardContent className="flex flex-col gap-3 p-5">
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-center gap-3">
                  <span className="flex size-10 items-center justify-center rounded-full bg-primary/10 text-primary">
                    {r.administers ? <ShieldCheck className="size-5" /> : <KeyRound className="size-5" />}
                  </span>
                  <div>
                    <p className="font-bold text-foreground">{roleLabel(r.name)}</p>
                    <p className="text-xs text-muted-foreground">{t("accountsCount", { count: r.accounts })}</p>
                  </div>
                </div>
                {r.administers && <Badge variant="default">{t("administersAccounts")}</Badge>}
              </div>
              <div className="flex flex-wrap gap-1.5">
                {r.permissions.length === 0 ? (
                  <span className="text-xs text-muted-foreground">{t("noPermissions")}</span>
                ) : (
                  r.permissions.map((p) => (
                    <Badge key={p} variant="secondary" className="font-mono text-[11px]">
                      {p}
                    </Badge>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="flex flex-col gap-4 rounded-xl border border-border bg-card p-5">
        <div className="flex flex-wrap items-center gap-2">
          <div className="min-w-60 flex-1">
            <SearchBox value={search.q ?? ""} busy={list.isFetching} placeholder={t("searchAccounts")} onSearch={(q) => set({ q: q || undefined, page: undefined })} wide />
          </div>
          <Select value={search.role ?? "__all"} onValueChange={(v) => set({ role: v === "__all" ? undefined : v, page: undefined })}>
            <SelectTrigger className="w-auto min-w-40 font-semibold">
              <span className="font-medium text-muted-foreground">{t("role")}:</span>
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              <SelectItem value="__all">{capitalize(t("all"))}</SelectItem>
              {realm.roles.map((r) => (
                <SelectItem key={r} value={r}>
                  {roleLabel(r)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={search.status ?? "__all"} onValueChange={(v) => set({ status: v === "__all" ? undefined : (v as Status), page: undefined })}>
            <SelectTrigger className="w-auto min-w-40 font-semibold">
              <span className="font-medium text-muted-foreground">{t("status")}:</span>
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              <SelectItem value="__all">{capitalize(t("all"))}</SelectItem>
              {(["active", "invited", "unverified", "disabled"] as Status[]).map((s) => (
                <SelectItem key={s} value={s}>
                  <span className={cn("size-2 rounded-full", STATUS[s].dot)} />
                  {statusLabel(s)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {list.isError && !page ? (
          <ErrorState error={list.error} onRetry={() => list.refetch()} />
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{realm.singular}</TableHead>
                <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{t("roles")}</TableHead>
                <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{t("status")}</TableHead>
                <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{t("lastSeenColumn")}</TableHead>
                <TableHead className="w-12" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {!page &&
                Array.from({ length: 5 }, (_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={5}>
                      <Skeleton className="h-9 w-full" />
                    </TableCell>
                  </TableRow>
                ))}
              {page?.items.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} className="py-12 text-center text-sm text-muted-foreground">
                    {t("noAccounts")}
                  </TableCell>
                </TableRow>
              )}
              {page?.items.map((a) => (
                <TableRow key={a.id}>
                  <TableCell className="py-3">
                    <div className="flex items-center gap-3">
                      <span className="flex size-10 shrink-0 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary">
                        {initials(a.name || a.email)}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate font-semibold text-foreground">
                          {a.name || a.email}
                          {mine(a) && <span className="ml-2 text-xs font-medium text-muted-foreground">({t("you")})</span>}
                        </p>
                        <p className="truncate text-xs text-muted-foreground">{a.email}</p>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-wrap gap-1">
                      {a.roles.length === 0 ? <span className="text-muted-foreground">—</span> : a.roles.map((r) => <Badge key={r} variant="secondary">{roleLabel(r)}</Badge>)}
                    </div>
                  </TableCell>
                  <TableCell>
                    <span className={cn("inline-flex items-center gap-2 font-semibold", STATUS[a.status].text)}>
                      <span className={cn("size-2 rounded-full", STATUS[a.status].dot)} />
                      {statusLabel(a.status)}
                    </span>
                  </TableCell>
                  <TableCell className="text-muted-foreground">{seen(a.last_seen_at)}</TableCell>
                  <TableCell>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon-sm" aria-label={t("actions")}>
                          <MoreHorizontal />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-56">
                        <DropdownMenuItem onClick={() => setEditing(a)}>
                          <ShieldCheck /> {t("changeRoles")}
                        </DropdownMenuItem>
                        {a.status === "invited" && (
                          <DropdownMenuItem
                            onClick={() => act.mutate(() => accounts.reinvite(a.id, inviteRedirect()).then(() => toast(t("inviteResent"))))}
                          >
                            <RotateCw /> {t("resendInvite")}
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuItem onClick={() => act.mutate(() => accounts.endSessions(a.id).then(() => toast(t("sessionsEnded"))))}>
                          <LogOut /> {t("endSessions")}
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        {a.status === "disabled" ? (
                          <DropdownMenuItem onClick={() => act.mutate(() => accounts.enable(a.id).then(() => toast(t("accountEnabled"))))}>
                            <UserCheck /> {t("enable")}
                          </DropdownMenuItem>
                        ) : (
                          <Guarded own={mine(a)}>
                            <DropdownMenuItem
                              disabled={mine(a)}
                              onClick={async () => {
                                if (await ask(t("disableQ", { name: a.name || a.email }), { kind: "warning", description: t("disableHint"), confirm: t("disable") })) {
                                  act.mutate(() => accounts.disable(a.id).then(() => toast(t("accountDisabled"))))
                                }
                              }}
                            >
                              <Ban /> {t("disable")}
                            </DropdownMenuItem>
                          </Guarded>
                        )}
                        <Guarded own={mine(a)}>
                          <DropdownMenuItem
                            disabled={mine(a)}
                            variant="destructive"
                            onClick={async () => {
                              if (await ask(t("deleteAccountQ", { name: a.name || a.email }), { destructive: true, description: t("cantUndo"), confirm: t("delete") })) {
                                act.mutate(() => accounts.remove(a.id).then(() => toast(t("deleted"))))
                              }
                            }}
                          >
                            <Trash2 /> {t("delete")}
                          </DropdownMenuItem>
                        </Guarded>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
        {page && page.total_pages > 1 && (
          <div className="flex items-center justify-between gap-3 text-sm">
            <p className="text-muted-foreground">{t("showing", { from: (page.page - 1) * 20 + 1, to: (page.page - 1) * 20 + page.items.length, total: page.total })}</p>
            <div className="flex items-center gap-1">
              <Button variant="ghost" size="icon-sm" disabled={page.page <= 1} onClick={() => set({ page: page.page - 1 })} aria-label={t("previous")}>
                <ChevronLeft />
              </Button>
              <span className="px-2 font-semibold tabular-nums">
                {page.page} / {page.total_pages}
              </span>
              <Button variant="ghost" size="icon-sm" disabled={page.page >= page.total_pages} onClick={() => set({ page: page.page + 1 })} aria-label={t("next")}>
                <ChevronRight />
              </Button>
            </div>
          </div>
        )}
      </div>

      <InviteDialog realm={realm} open={inviting} onOpenChange={setInviting} onInvited={refresh} />
      <RolesDialog realm={realm} account={editing} own={editing ? mine(editing) : false} onClose={() => setEditing(null)} onSaved={refresh} />
    </div>
  )
}

/** An action that would lock one out of one's own account: disabled, and says why. */
function Guarded({ own, children }: { own: boolean; children: React.ReactNode }) {
  if (!own) return <>{children}</>
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div>{children}</div>
      </TooltipTrigger>
      <TooltipContent side="left">{t("ownAccountHint")}</TooltipContent>
    </Tooltip>
  )
}

/** The roles of the realm, to check: each with what it administers. */
function RoleChecks({ realm, value, onChange, locked = [] }: { realm: AccountRealm; value: string[]; onChange: (v: string[]) => void; locked?: string[] }) {
  return (
    <div className="flex flex-col gap-1">
      {realm.roles.map((r) => (
        <label key={r} className="flex h-10 cursor-pointer items-center justify-between gap-3 rounded-lg px-2 text-sm font-semibold hover:bg-muted">
          {roleLabel(r)}
          <Checkbox
            checked={value.includes(r)}
            disabled={locked.includes(r)}
            onCheckedChange={(c) => onChange(c ? [...value, r] : value.filter((x) => x !== r))}
          />
        </label>
      ))}
    </div>
  )
}

/** Invite someone: their email, the account's fields, its roles. */
function InviteDialog({ realm, open, onOpenChange, onInvited }: { realm: AccountRealm; open: boolean; onOpenChange: (o: boolean) => void; onInvited: () => void }) {
  const [email, setEmail] = useState("")
  const [fields, setFields] = useState<Record<string, string>>({})
  const [roles, setRoles] = useState<string[]>([])
  const [errors, setErrors] = useState<Record<string, string>>({})
  const invite = useMutation({
    mutationFn: () => accountsOf(realm).invite({ email, roles, fields, redirect: inviteRedirect() }),
    onSuccess: () => {
      toast(t("inviteSent", { email }))
      onInvited()
      onOpenChange(false)
    },
    onError: (e) => {
      if (isApiError(e) && e.code === "email_taken") return setErrors({ email: t("emailTaken") })
      if (isApiError(e) && e.code === "invalid_email") return setErrors({ email: describe(e) })
      const byField = Object.fromEntries(
        Object.entries(fieldErrors(e)).map(([name, code]) => {
          const f = realm.fields.find((x) => x.name === name)
          return [name, f ? fieldMessage(f, code) : code]
        }),
      )
      if (Object.keys(byField).length) return setErrors(byField)
      toast(describe(e), "error")
    },
  })
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (o) {
          setEmail("")
          setFields({})
          setRoles([])
          setErrors({})
        }
        onOpenChange(o)
      }}
    >
      <DialogContent className="sm:max-w-md">
        <form
          className="flex flex-col gap-5"
          onSubmit={(e) => {
            e.preventDefault()
            setErrors({})
            invite.mutate()
          }}
        >
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <MailPlus className="size-5 text-primary" /> {t("inviteTitleTo", { name: realm.singular })}
            </DialogTitle>
            <DialogDescription>{t("inviteDialogHint")}</DialogDescription>
          </DialogHeader>
          <FieldGroup className="gap-4">
            <Field data-invalid={errors.email ? true : undefined}>
              <FieldLabel htmlFor="invite-email">{t("email")}</FieldLabel>
              <Input id="invite-email" type="email" required autoFocus value={email} onChange={(e) => setEmail(e.target.value)} aria-invalid={errors.email ? true : undefined} />
              {errors.email && <FieldError>{errors.email}</FieldError>}
            </Field>
            {realm.fields.map((f) => (
              <Field key={f.name} data-invalid={errors[f.name] ? true : undefined}>
                <FieldLabel htmlFor={`invite-${f.name}`}>{f.label}</FieldLabel>
                {f.kind === "enum" ? (
                  <Select value={fields[f.name] ?? ""} onValueChange={(v) => setFields({ ...fields, [f.name]: v })}>
                    <SelectTrigger id={`invite-${f.name}`}>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {(f.values ?? []).map((v) => (
                        <SelectItem key={v} value={v}>
                          {format(f, v)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <Input id={`invite-${f.name}`} required={f.required} value={fields[f.name] ?? ""} onChange={(e) => setFields({ ...fields, [f.name]: e.target.value })} />
                )}
                {errors[f.name] && <FieldError>{errors[f.name]}</FieldError>}
              </Field>
            ))}
            {realm.roles.length > 0 && (
              <Field>
                <FieldLabel>{t("roles")}</FieldLabel>
                <RoleChecks realm={realm} value={roles} onChange={setRoles} />
              </Field>
            )}
          </FieldGroup>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              {t("cancel")}
            </Button>
            <Button type="submit" disabled={invite.isPending || !email}>
              <MailPlus /> {t("sendInvite")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

/** Change an account's roles; one's own administering role stays. */
function RolesDialog({
  realm,
  account,
  own,
  onClose,
  onSaved,
}: {
  realm: AccountRealm
  account: Account | null
  own: boolean
  onClose: () => void
  onSaved: () => void
}) {
  const [roles, setRoles] = useState<string[]>([])
  const [shown, setShown] = useState<string | null>(null)
  if (account && shown !== account.id) {
    setShown(account.id)
    setRoles(account.roles)
  }
  const adminRoles = realm.admins.filter((a) => a.startsWith(`${realm.name}.`)).map((a) => a.split(".")[1])
  const save = useMutation({
    mutationFn: () => accountsOf(realm).setRoles(account!.id, roles),
    onSuccess: () => {
      toast(t("rolesSaved"))
      onSaved()
      onClose()
    },
    onError: (e) => toast(describe(e), "error"),
  })
  return (
    <Dialog
      open={account !== null}
      onOpenChange={(o) => {
        if (!o) {
          setShown(null)
          onClose()
        }
      }}
    >
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>{t("changeRoles")}</DialogTitle>
          <DialogDescription>{account?.name || account?.email}</DialogDescription>
        </DialogHeader>
        <RoleChecks realm={realm} value={roles} onChange={setRoles} locked={own ? adminRoles.filter((r) => account?.roles.includes(r)) : []} />
        {own && <p className="text-xs text-muted-foreground">{t("ownAccountHint")}</p>}
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            {t("cancel")}
          </Button>
          <Button disabled={save.isPending} onClick={() => save.mutate()}>
            {t("save")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
